import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.println(input.nextInt() + input.nextInt());
        Scanner s = new Scanner("  -7 9223372036854775807 bad  true\n");
        System.out.println(s.hasNextInt() + ":" + s.hasNextInt() + ":" + s.nextInt());
        System.out.println(s.nextLong());
        try { s.nextInt(); } catch (InputMismatchException e) { System.out.println("mismatch:" + s.next()); }
        System.out.println(s.nextBoolean() + ":" + s.hasNext());
        try { s.next(); } catch (NoSuchElementException e) { System.out.println("eof"); }
        s.close();
        try { s.hasNext(); } catch (IllegalStateException e) { System.out.println("closed"); }
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner("ff 101 123456789012345678901234567890 1,234.5 -0.125 NaN Infinity").useLocale(Locale.US);
        System.out.println(s.nextInt(16) + ":" + s.nextInt(2) + ":" + s.nextBigInteger());
        System.out.println(s.nextDouble() + ":" + s.nextBigDecimal() + ":" + s.nextDouble() + ":" + s.nextDouble());
        s = new Scanner("20,5 1.234,25").useLocale(Locale.GERMANY);
        System.out.println(s.nextDouble() + ":" + s.nextDouble());
        s = new Scanner("１２ ٣٤");
        System.out.println(s.nextInt() + ":" + s.nextInt());
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner("20\nhello 世界\r\nlast");
        System.out.println(s.nextInt() + ":" + s.nextLine().length());
        while (s.hasNextLine()) System.out.println(s.nextLine());
        s = new Scanner("one,two,,four").useDelimiter(",");
        while (s.hasNext()) System.out.println("[" + s.next() + "]");
        s = new Scanner("a1 b22 c333");
        System.out.println(s.findWithinHorizon("[0-9]+", 0));
        System.out.println(s.findAll("[0-9]+").map(m -> m.group()).reduce((a,b) -> a+":"+b).orElse("empty"));
        System.out.println(new Scanner("a b c").tokens().count());
    }
}

