import java.util.regex.*;
import java.text.*;
import java.util.*;
public class Main {
    public static void main(String[] args) {
        for (String regex : new String[]{"\\x{2c}", "\\x{1F600}", "[\\x{41}-\\x{5A}]+", "\\x{00000041}"}) {
            String text = regex.contains("2c") ? "," : regex.contains("1F") ? "😀" : "AZ";
            System.out.println(Pattern.compile(regex).matcher(text).find());
        }
        for (String regex : new String[]{"\\x{}", "\\x{110000}", "\\x{0g}", "\\x{41", "\\x{ＦＦ}"}) {
            try { Pattern.compile(regex); System.out.println("accepted"); }
            catch (PatternSyntaxException e) { System.out.println("rejected"); }
        }
        DecimalFormat format = (DecimalFormat) NumberFormat.getNumberInstance(Locale.US);
        System.out.println("["+format.getPositivePrefix()+"]["+format.getPositiveSuffix()+"]["+format.getNegativePrefix()+"]["+format.getNegativeSuffix()+"]");
        Locale previous = Locale.getDefault();
        Locale.setDefault(Locale.US);
        Locale.setDefault(Locale.Category.FORMAT, Locale.GERMANY);
        System.out.println(Locale.getDefault() + ":" + Locale.getDefault(Locale.Category.DISPLAY) + ":" + Locale.getDefault(Locale.Category.FORMAT));
        Locale.setDefault(previous);
    }
}

import java.util.*;
import java.math.*;
public class Main {
    enum Kind { A, B }
    public static void main(String[] args) {
        Map<String,Integer> map = new TreeMap<>();
        for (String value : Arrays.asList("b","a","b")) map.merge(value, 1, Integer::sum);
        System.out.println(map);
        System.out.println(Arrays.asList(1,2,3).stream().mapToInt(Integer::intValue).sum());
        System.out.println(new BigInteger("12345678901234567890").multiply(new BigInteger("1000")));
        System.out.println(EnumSet.allOf(Kind.class));
        Object[] objects = new Object[2]; objects[0] = "hello";
        System.out.println(Arrays.copyOf(objects, 3)[0]);
    }
}

